function CandidateProgress({ candidate }: { candidate: CandidateRecord }) {
  const hasProgress = Number.isFinite(candidate.progressPercent);
  const value = hasProgress
    ? Math.min(100, Math.max(0, Math.round(candidate.progressPercent!)))
    : null;
  const milestone = candidate.progressMilestone?.trim() || WORKFLOW_LABELS[candidate.status];
  return (
    <span className="candidate-progress">
      <span className="progress-copy">
        {milestone}{value === null ? "" : ` · ${value}%`}
      </span>
      <span
        className="progress-track"
        role={value === null ? undefined : "progressbar"}
        aria-label={`Прогресс обработки: ${milestone}`}
        aria-valuenow={value ?? undefined}
        aria-valuemin={value === null ? undefined : 0}
        aria-valuemax={value === null ? undefined : 100}
      >
        <i style={{ width: value === null ? "0" : `${value}%` }} />
      </span>
    </span>
  );
}
