  active: vacancy.active !== false,
  archived: vacancy.archived === true,
  short: vacancy.title,
  avatar: vacancy.title.slice(0, 2).toUpperCase(),
  color: VACANCY_COLORS[index % VACANCY_COLORS.length],
});
