ex:1;text-align:center;transform:rotate(-12deg)}.donut small,.donut strong{display:block}.donut small{font-size:11px;color:var(--muted)}.donut strong{font-size:25px;margin-top:2px}.result-legend{display:grid;gap:7px}.result-legend span{display:grid;grid-template-columns:8px 22px 1fr;align-items:center;font-size:11px;color:var(--muted)}.result-legend i{width:7px;height:7px;border-radius:3px}.result-legend i.green{background:#55dec0}.result-legend i.yellow{background:#ffc87c}.result-legend i.red{background:#89a8ff}.result-legend b{color:var(--ink);font-size:11px}.attention-panel{padding:18px 20px}.attention-list{margin-top:10px}.attention-list>button{width:100%;border:0;border-top:1px solid #eff0f2;background:white;display:grid;grid-template-columns:38px minmax(180px,1fr) 120px 90px 16px;gap:12px;align-items:center;text-align:left;padding:12px 5px;cursor:pointer;border-radius:8px}.attention-list>button:hover{background:#f8fbfd}.per`... 88245 more characters, expected: /\.materials-compact\s*>\s*div:not\(\.panel-head\):not\(\.result-materials\)\s*\{/, operator: 'match', diff: 'simple' } }
